"Optional · selected task evidence is sent to TypeSafe when you run. Provider usage charges apply. PandaCode works without Jev. Advice does not change files, models, or permissions.": "省略可能 · 実行時に選択したタスクのエビデンスを TypeSafe に送信します。プロバイダーの利用料金がかかります。PandaCode は Jev なしでも動作します。アドバイスがファイル、モデル、権限を変更することはありません。",
"Optional, such as us-central1": "省略可能（例：us-central1）",
"Optional. Leave blank for no token limit.": "省略可能。空欄にすると token 上限はありません。",
"Optional. Tone, values and conversational style, kept apart from the instructions. Importing copies the file once; later changes to the file do not change the bot. Personality never grants tools or permissions.": "省略可能。トーン、価値観、会話スタイルの設定で、指示とは別に保存されます。インポートはファイルを 1 回コピーするだけです。その後のファイル変更は Bot に反映されません。パーソナリティがツールや権限を付与することはありません。",
