"PandaCode has no “{0}” view. Showing its data instead.": "PandaCode に「{0}」ビューはありません。代わりにそのデータを表示しています。",
"PandaCode quick launcher": "PandaCode クイックランチャー",
"PandaCode restarts when your agents are done and you step away.": "Agent が完了し、あなたが離席すると PandaCode は再起動します。",
"PandaCode runs Linux and macOS VMs on Apple's Virtualization framework: headless, and only the memory you give it.": "PandaCode は Apple の Virtualization フレームワーク上で Linux と macOS の VM を実行します。ヘッドレスで、割り当てたメモリだけを使用します。",
"PandaCode tools": "PandaCode ツール",
"PandaCode uses it to check that messages really come from Meta.": "PandaCode は、メッセージが本当に Meta から来たものか検証するために使います。",
"PandaCode will restart to update when your agents finish.": "Agent の完了後、PandaCode は更新のために再起動します。",
"PandaCode works without Jev or a TypeSafe key. Optional decision assistance only needs the key for the provider you pick. OpenRouter models are listed only when you open the model menu. Keys are saved privately on this device, outside the keychain. Leave a field empty to keep its saved key.": "PandaCode は Jev や TypeSafe キーなしでも動作します。省略可能な決定アシストには、選択したプロバイダーのキーだけが必要です。OpenRouter モデルはモデルメニューを開いたときにだけ表示されます。キーはこのデバイス上の、キーチェーン外の非公開の場所に保存されます。フィールドを空のままにすると、保存済みのキーが維持されます。",
"PandaCode {0} is available.": "PandaCode {0} が利用可能です。",
"PandaCode {0} is available. Installs when your agents are done.": "PandaCode {0} が利用可能です。Agent の完了後にインストールされます。",
"PandaCode {0} is available. Open GitHub Releases to update this copy.": "PandaCode {0} が利用可能です。GitHub Releases を開いてこのコピーを更新してください。",
"PandaCode {0} is available. Updates for this copy are installed by its package or a new AppImage.": "PandaCode {0} が利用可能です。このコピーの更新はパッケージまたは新しい AppImage でインストールされます。",
"PandaCode {0} is ready. Restart now, or it restarts on its own when your agents are done.": "PandaCode {0} の準備ができました。今すぐ再起動するか、Agent の完了後に自動で再起動します。",
