"Read-only: Grok investigates and proposes a plan; edits and commands are declined.": "読み取り専用：Grok が調査し、プランを提案します。編集とコマンドは拒否されます。",
"Read-only: Kilo investigates and plans; edits, commands and other state-changing tools are declined.": "読み取り専用：Kilo が調査と計画を行います。編集、コマンド、その他の状態変更ツールは拒否されます。",
"Read-only: Muse cannot write files or run shell commands, and proposes a plan.": "読み取り専用：Muse はファイルの書き込みやシェルコマンドの実行ができず、プランを提案します。",
