"Reads account limits from your locally configured agent accounts. Requests go directly to the provider or its CLI, never through PandaCode servers. No prompts are sent. Results are cached for one minute; Refresh is limited to once every ten seconds per provider. Some providers do not expose their limits. Usage is shared with other apps using the same account.": "ローカルで設定した Agent アカウントからアカウント上限を読み取ります。リクエストはプロバイダーまたはその CLI に直接送られ、PandaCode のサーバーを経由しません。プロンプトは送信されません。結果は 1 分間キャッシュされ、再読み込みはプロバイダーごとに 10 秒に 1 回までです。上限を公開していないプロバイダーもあります。使用量は同じアカウントを使う他のアプリと共有されます。",
