"Use a shortcut such as CommandOrControl+Shift+Space.": "CommandOrControl+Shift+Space のようなショートカットを使用してください。",
"Use a single agent": "単一の Agent を使用",
"Use a single slash command without control characters.": "制御文字を含まない単一のスラッシュコマンドを使用してください。",
"Use a worktree": "ワークツリーを使用",
"Use an HTTP or HTTPS URL without embedded credentials.": "認証情報を含まない HTTP または HTTPS の URL を使用してください。",
"Use an HTTP or HTTPS address without embedded credentials.": "認証情報を含まない HTTP または HTTPS のアドレスを使用してください。",
"Use an account token, or a workspace token with its workspace ID. Agents run the Railway CLI with it (fetched on first use if it is not installed); it never enters their prompts.": "アカウントトークンか、ワークスペース ID 付きのワークスペーストークンを使用します。Agent はそれで Railway CLI を実行します（未インストールなら初回使用時に取得）。トークンがプロンプトに入ることはありません。",
"Use custom model": "カスタムモデルを使用",
"Use from my phone and other devices": "スマホや他のデバイスから使用",
"Use letters, numbers, hyphens, underscores, and slashes.": "英字、数字、ハイフン、アンダースコア、スラッシュを使用できます。",
"Use other answer": "その他の回答を使用",
"Use regular expression": "正規表現を使用",
"Use report in prompt": "レポートをプロンプトに使用",
"Use the existing branch instead of creating one": "新しく作らず既存のブランチを使用",
"Use the harness's saved settings.{0}": "Agent の保存済み設定を使用します。{0}",
"Use the harness’s advertised MCP commands. Refresh the slash-command menu to sync the current list.": "Agent が公開している MCP コマンドを使用します。スラッシュコマンドメニューを再読み込みすると現在のリストに同期します。",
"Use the harness’s normal rules. Ask you when approval is needed.": "Agent の通常のルールを使用します。承認が必要なときは確認します。",
"Use this agent’s package manager to update it.": "この Agent 自身のパッケージマネージャーで更新します。",
"Use up to 8 rules, with no more than 500 characters per rule.": "最大 8 ルールを使用します。各ルールは 500 文字以内にしてください。",
