"Uses your AWS CLI sign-in (run `aws login` first). Desktops have no open ports; PandaCode reaches them through Systems Manager, which needs the Session Manager plugin for screens.": "AWS CLI のログインを使用します（先に `aws login` を実行）。デスクトップはポートを開きません。PandaCode は Systems Manager 経由でアクセスし、画面には Session Manager プラグインが必要です。",
"Uses your installed gcloud CLI and its sign-in (run `gcloud auth login` first); PandaCode downloads nothing and stores only the project, region and zone.": "インストール済みの gcloud CLI とそのログインを使用します（先に `gcloud auth login` を実行）。PandaCode は何もダウンロードせず、プロジェクト、リージョン、ゾーンだけを保存します。",
