"Copilot CLI's interactive console does not accept PandaCode reasoning overrides.": "Copilot CLI のインタラクティブコンソールは PandaCode の推論の強さの上書きを受け付けません。",
"Could not identify the cloud machine's Linux architecture.": "クラウドマシンの Linux アーキテクチャを特定できませんでした。",
"Could not inspect pandacode-run.sh.": "pandacode-run.sh を調査できませんでした。",
"Could not keep a connection to the desktop.": "デスクトップへの接続を維持できませんでした。",
"Could not lock subagent snapshots.": "サブ Agent のスナップショットをロックできませんでした。",
"Could not open the browser.": "ブラウザーを開けませんでした。",
"Could not reach the desktop through Systems Manager. If the instance just started, wait a minute; the desktop installs on first boot.": "Systems Manager 経由でデスクトップに到達できませんでした。インスタンスを起動したばかりなら 1 分待ってください。デスクトップは初回起動時にインストールされます。",
"Could not read the local OpenCode login file. Check its permissions and sign in again if needed.": "ローカルの OpenCode ログインファイルを読み取れませんでした。権限を確認し、必要なら再ログインしてください。",
"Could not read the saved harness state archive.": "保存済みの Agent 状態アーカイブを読み取れませんでした。",
"Could not upload a file to the cloud machine.": "クラウドマシンにファイルをアップロードできませんでした。",
"Could not upload a login file to the cloud machine.": "クラウドマシンにログインファイルをアップロードできませんでした。",
"Create a new task to use a different project after a conversation has started.": "会話の開始後に別のプロジェクトを使うには、新しいタスクを作成してください。",
"Create a new task to use a different provider after a conversation has started.": "会話の開始後に別のプロバイダーを使うには、新しいタスクを作成してください。",
"Declined by the user": "ユーザーによって拒否されました",
"Default team settings only apply to a new user task.": "デフォルトのチーム設定は新しいユーザータスクにのみ適用されます。",
"Dependencies must be previously returned worker IDs.": "依存関係には、以前に返された worker ID を指定してください。",
"Describe a task in fewer than 32,768 characters.": "タスクの説明は 32,768 文字未満にしてください。",
"Describe the browser test in 8,192 characters or fewer.": "ブラウザーテストの説明は 8,192 文字以内にしてください。",
"Describe the context or worker assignment you need.": "必要なコンテキストまたは worker への割り当てを記述してください。",
"Design file grew while reading.": "読み取り中にデザインファイルが大きくなりました。",
"Design files must be regular files, not links.": "デザインファイルは通常のファイルにしてください。リンクは不可です。",
"Devin did not return a session ID.": "Devin がセッション ID を返しませんでした。",
"Docker is installed but not running. Start Docker Desktop and try again.": "Docker はインストールされていますが実行されていません。Docker Desktop を起動して再試行してください。",
"Each image must be 12 MB or smaller.": "各画像は 12 MB 以下にしてください。",
"Each image must be 24 MB or smaller.": "各画像は 24 MB 以下にしてください。",
"Each project rule needs 1–500 characters on one line.": "各プロジェクトルールは 1 行で 1–500 文字にしてください。",
"Each screenshot must be a PNG file smaller than 5 MB": "各スクリーンショットは 5 MB 未満の PNG ファイルにしてください",
"Each screenshot must be smaller than 5 MB": "各スクリーンショットは 5 MB 未満にしてください",
"Enable Jev browser testing in Settings first.": "先に Settings で Jev ブラウザーテストを有効化してください。",
"Enable decision assistance in Jev settings first. Normal PandaCode tasks do not need Jev.": "先に Jev 設定で決定アシストを有効化してください。通常の PandaCode タスクに Jev は不要です。",
"Enter a boat API key (`boat api-key create pandacode --preset ci`).": "boat の API キーを入力してください（`boat api-key create pandacode --preset ci`）。",
"Enter a goal between 1 and 32,768 bytes.": "ゴールは 1 から 32,768 バイトの間にしてください。",
"Enter a goal under 32 KiB and an optional positive token budget.": "32 KiB 未満のゴールと、省略可能な正の token 予算を入力してください。",
"Enter a pull request number or its GitHub URL.": "Pull Request の番号または GitHub URL を入力してください。",
"Enter a text model identifier.": "テキストモデルの識別子を入力してください。",
"Enter a valid API key.": "有効な API キーを入力してください。",
"Enter a valid HTTP or HTTPS URL.": "有効な HTTP または HTTPS URL を入力してください。",
"Enter an HTTP or HTTPS URL.": "HTTP または HTTPS の URL を入力してください。",
"Enter an InstaBox API key (ibk_…).": "InstaBox の API キーを入力してください（ibk_…）。",
"Enter the WhatsApp phone number ID (digits only) from Meta's API Setup page.": "Meta の API Setup ページにある WhatsApp の電話番号 ID（数字のみ）を入力してください。",
"Enter the WhatsApp phone number ID from Meta's API setup page.": "Meta の API setup ページにある WhatsApp の電話番号 ID を入力してください。",
"Enter the phone number ID (digits only) from WhatsApp → API Setup. It is not the phone number itself.": "WhatsApp → API Setup の電話番号 ID（数字のみ）を入力してください。電話番号そのものではありません。",
"Enter your Blaxel API key.": "Blaxel の API キーを入力してください。",
"Enter your Blaxel workspace.": "Blaxel のワークスペースを入力してください。",
"Enter your E2B API key.": "E2B の API キーを入力してください。",
"Enter your Runloop API key.": "Runloop の API キーを入力してください。",
"Environment variable names use letters, digits and underscores, and do not start with a digit.": "環境変数名には英字、数字、アンダースコアが使え、数字で始めてはいけません。",
"Every worker must complete or be explicitly abandoned before finishing. Follow up or cancel failed work with a reason.": "終了前に、すべての worker が完了するか明示的に放棄されている必要があります。失敗した作業は理由を付けてフォローアップするかキャンセルしてください。",
"File exceeds the 128 KiB preview limit": "ファイルが 128 KiB のプレビュー上限を超えています",
"File scopes must be normalized relative paths without wildcards.": "ファイルスコープは、ワイルドカードなしの正規化された相対パスにしてください。",
"File search queries must be at most 512 bytes and contain no null characters.": "ファイル検索のクエリは最大 512 バイトで、null 文字を含まないようにしてください。",
"Finish Jev assessments before updating an agent.": "Agent を更新する前に、Jev のアセスメントを完了させてください。",
"Finish Jev browser tests and setup before updating an agent.": "Agent を更新する前に、Jev のブラウザーテストとセットアップを完了させてください。",
"Finish running agents and close terminals before updating an agent.": "Agent を更新する前に、実行中の Agent を完了させ、ターミナルを閉じてください。",
