"Git status exceeds the 1 MiB inspection limit": "Git ステータスが 1 MiB の調査上限を超えています",
"GitHub Copilot CLI does not advertise the selected task mode. Update Copilot CLI, then refresh.": "GitHub Copilot CLI が選択されたタスクモードを公開していません。Copilot CLI を更新してから、再読み込みしてください。",
"GitHub Copilot CLI requires sign-in. Run `copilot login` in a terminal, then retry.": "GitHub Copilot CLI にはログインが必要です。ターミナルで `copilot login` を実行してから再試行してください。",
"GitHub returned an unexpected repository list.": "GitHub が予期しないリポジトリ一覧を返しました。",
"GitHub returned an unexpected sign-in code.": "GitHub が予期しないログインコードを返しました。",
"Give a bundle identifier such as com.example.App.": "com.example.App のようなバンドル識別子を指定してください。",
"Give an Android package name such as com.example.app.": "com.example.app のような Android パッケージ名を指定してください。",
"Give at most one typed answer": "入力型の回答は最大 1 つにしてください",
