"Give the skill a name in its frontmatter.": "Skill の frontmatter に名前を付けてください。",
"Goal controls cannot include attachments or skills. Add these in a separate message.": "ゴールのコントロールに添付や Skill は含められません。別のメッセージで追加してください。",
