"Only macOS VMs can be suspended. Stop a Linux VM instead; it boots in seconds.": "サスペンドできるのは macOS の VM のみです。代わりに Linux VM を停止してください。数秒で起動します。",
"Only regular text files can be previewed": "プレビューできるのは通常のテキストファイルのみです",
"Only simple object forms are supported": "対応しているのはシンプルなオブジェクト形式のフォームのみです",
"Only the main window can check agent updates.": "Agent の更新を確認できるのはメインウィンドウのみです。",
"Only the main window can delete tasks.": "タスクを削除できるのはメインウィンドウのみです。",
"Only the main window can discard new tasks.": "新しいタスクを破棄できるのはメインウィンドウのみです。",
"Only the main window can update agents.": "Agent を更新できるのはメインウィンドウのみです。",
"Only web channels have a chat link.": "チャットリンクがあるのは web チャンネルのみです。",
"Open a Git repository to create a pull request.": "Pull Request を作成するには Git リポジトリを開いてください。",
"Open the Git repository's root folder to use Git actions": "Git 操作を使うには Git リポジトリのルートフォルダを開いてください",
