"PandaCode only connects to VM screens on this Mac.": "PandaCode が接続できる VM 画面はこの Mac 上のものだけです。",
"PandaCode only controls InstaBox machines it created.": "PandaCode が操作できるのは、自分が作成した InstaBox マシンだけです。",
"PandaCode tool timed out": "PandaCode ツールがタイムアウトしました",
"Paste a CodeSandbox API key first.": "先に CodeSandbox の API キーを貼り付けてください。",
"Paste a Freestyle API key first.": "先に Freestyle の API キーを貼り付けてください。",
"Paste the token from claude setup-token.": "claude setup-token のトークンを貼り付けてください。",
"Path must stay inside the repository.": "パスはリポジトリ内に収まる必要があります。",
"Pause active goals before updating an agent.": "Agent を更新する前に、実行中のゴールを一時停止してください。",
"Pause active teams before updating an agent.": "Agent を更新する前に、アクティブなチームを一時停止してください。",
"Pause the architect team before changing this task.": "このタスクを変更する前に、Architect チームを一時停止してください。",
"Pause the goal before opening its harness console.": "Agent コンソールを開く前に、ゴールを一時停止してください。",
"Pause the task goal before enabling architect mode.": "Architect モードを有効化する前に、タスクのゴールを一時停止してください。",
"Pause this task's active goal before deleting it.": "このタスクを削除する前に、実行中のゴールを一時停止してください。",
