"Prepare the evidence again before running Jev.": "Jev を実行する前に、エビデンスを再準備してください。",
"Preview versions use their own release channel. Update this installation with its official CLI or package manager.": "プレビューバージョンは独自のリリースチャンネルを使います。このインストールは、公式の CLI またはパッケージマネージャーで更新してください。",
"Price list is unexpectedly large.": "価格表が異常に大きいです。",
