"Provider output exceeded the message size limit": "プロバイダーの出力がメッセージサイズの上限を超えました",
"Provider sent an oversized JSON message": "プロバイダーが大きすぎる JSON メッセージを送信しました",
"Provider settings file is too large.": "プロバイダー設定ファイルが大きすぎます。",
"Queued attachments are invalid or too large.": "キュー中の添付が無効か、大きすぎます。",
"Queued messages must be under 128 KiB.": "キュー中のメッセージは 128 KiB 未満にしてください。",
"RTK is already being installed.": "RTK は既にインストール中です。",
"Railway machines can only be deleted.": "Railway のマシンは削除のみ可能です。",
"Reading PDF and Office documents is available on macOS. Attach a text export instead.": "PDF と Office ドキュメントの読み取りは macOS でのみ利用できます。代わりにテキストエクスポートを添付してください。",
"Recipe names use lowercase letters, digits, - and _ (up to 64).": "レシピ名には英小文字、数字、-、_ が使えます（最大 64 文字）。",
"Recipient does not belong to this active team.": "受信者はこのアクティブなチームに属していません。",
"Reduce the browser panel size before taking a screenshot.": "スクリーンショットを撮る前に、ブラウザーパネルのサイズを縮小してください。",
"Reopen this task first.": "先にこのタスクを開き直してください。",
"Reorder between 1 and 500 conversations at a time.": "一度に並べ替えられる会話は 1 から 500 件です。",
"Reorder pinned and unpinned conversations separately.": "ピン留めした会話と未ピン留めの会話は別々に並べ替えてください。",
"Report at most 200 paths per batch.": "バッチあたり最大 200 個のパスを報告してください。",
"Response contains an option that was not offered": "応答に提示されていないオプションが含まれています",
"Response is too large.": "応答が大きすぎます。",
"Restore or reopen the parent task before resuming the team.": "チームを再開する前に、親タスクを復元または開き直してください。",
"Restore or reopen the task and stop its agent before starting it.": "開始する前に、タスクを復元または開き直し、その Agent を停止してください。",
"Restore the parent task before coordinating work.": "作業を調整する前に、親タスクを復元してください。",
"Restore this task and stop its agent before changing its stage.": "ステージを変更する前に、このタスクを復元し、その Agent を停止してください。",
"Restore this task and stop its agent before editing its details.": "詳細を編集する前に、このタスクを復元し、その Agent を停止してください。",
"Resume or stop the pending team before starting another request.": "別のリクエストを開始する前に、待機中のチームを再開または停止してください。",
"Run Script has an invalid preview destination.": "Run Script のプレビュー先が無効です。",
"Run Script must be a regular file inside this workspace.": "Run Script はこのワークスペース内の通常のファイルにしてください。",
"Run Script must be no larger than 64 KiB.": "Run Script は 64 KiB 以下にしてください。",
