"Sandbox names use lowercase letters, digits and dashes (up to 63).": "サンドボックス名には英小文字、数字、ハイフンが使えます（最大 63 文字）。",
"Save up to 20 team profiles. Update or delete one first.": "保存できるチームプロファイルは最大 20 個です。先に 1 つ更新または削除してください。",
