"Screenshots in one message must total less than 12 MB": "1 メッセージ内のスクリーンショットの合計は 12 MB 未満にしてください",
"Scroll direction is up, down, left or right.": "スクロール方向は上、下、左、右のいずれかです。",
"Search for 1 to 200 characters.": "検索語は 1 から 200 文字にしてください。",
