"Seeing AWS desktops needs the Session Manager plugin. Install it with `brew install --cask session-manager-plugin`, then try again.": "AWS デスクトップの表示には Session Manager プラグインが必要です。`brew install --cask session-manager-plugin` でインストールしてから再試行してください。",
